#!/usr/bin/env python3
from __future__ import annotations
import json,re,sys
from pathlib import Path
BOOK='computer-fundamentals';BOOK_VERSION='2026.07.30-2';CANVA_DESIGN_ID='DAHQ5HKTq5M';CANVA_EDIT_URL='https://www.canva.com/d/pgWvtGBlDcRP0Nd';VP_ASSET='assets/computer-fundamentals-svg/computing-map.svg';VP_MARKER='data-vp-asset="computer-data-hardware-os-network-program-security-map"'
def nxt(v):m=re.fullmatch(r'(\d{4}\.\d{2}\.\d{2})-(\d+)',v);assert m;return f'{m.group(1)}-{int(m.group(2))+1}'
def svg_text():
 return '''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 1280" role="img" aria-labelledby="title desc"><title id="title">計算機概論資料硬體作業系統網路程式與安全判斷地圖</title><desc id="desc">陌生題先定位系統層，再固定單位與抽象層，依資料流處理硬體、作業系統、網路、程式、資料與安全。</desc><rect width="900" height="1280" rx="30" fill="#f3f8fb"/><rect x="34" y="34" width="832" height="184" rx="24" fill="#075985"/><text x="68" y="88" font-size="29" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#fff">計算機概論｜資料 → 硬體 → OS → 網路 → 程式 → 安全判斷地圖</text><text x="68" y="136" font-size="16" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#dff5ff">陌生題先定位系統哪一層，再處理單位、抽象層與前提；關鍵字不是答案。</text><text x="68" y="178" font-size="16" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#c7efff">定位系統層 → 固定單位 → 選模型／協定 → 檢查安全邊界 → 回到資料流</text><rect x="42" y="246" width="816" height="218" rx="22" fill="#fff" stroke="#0284c7" stroke-width="3"/><text x="70" y="292" font-size="24" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#0369a1">① 資料表示與硬體</text><text x="70" y="336" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#173042">bit／byte、十進／二進／十六進先統一單位；4 KiB＝4096 bytes。</text><text x="70" y="374" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#173042">CPU 效能拆成 clock、instruction count、CPI；2 GHz 一 cycle＝0.5 ns。</text><text x="70" y="412" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#173042">memory hierarchy 看容量、速度、locality；virtual memory 不等於 RAM 擴充。</text><text x="70" y="446" font-size="15" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#0369a1">數值先看單位，效能先拆瓶頸。</text><rect x="42" y="490" width="816" height="218" rx="22" fill="#fff" stroke="#0f766e" stroke-width="3"/><text x="70" y="536" font-size="24" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#0f766e">② OS、資料結構與資料庫</text><text x="70" y="580" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#173042">process 與 thread 分清資源邊界；page fault 是頁面不在實體記憶體。</text><text x="70" y="618" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#173042">資料結構依存取／插入／刪除需求選擇；Big-O 是成長上界，Θ 是同階緊界。</text><text x="70" y="656" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#173042">資料庫先找 key、relation、transaction 與 ACID，再判正規化或交易問題。</text><text x="70" y="690" font-size="15" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#0f766e">抽象層不同，問題也不同。</text><rect x="42" y="734" width="816" height="218" rx="22" fill="#fff" stroke="#b45309" stroke-width="3"/><text x="70" y="780" font-size="24" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#92400e">③ 網路與 Web</text><text x="70" y="824" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#173042">switch／router、MAC／IP、DNS／HTTP 各自解不同層問題。</text><text x="70" y="862" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#173042">TCP：可靠、依序 byte stream；UDP 不保證 delivery／duplicate protection。</text><text x="70" y="900" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#173042">HTTP/3 使用 QUIC，QUIC 整合 TLS 1.3；bandwidth 與 latency 分開。</text><text x="70" y="934" font-size="15" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#92400e">100 Mb/s 理論值＝12.5 MB/s。</text><rect x="42" y="978" width="816" height="198" rx="22" fill="#fff" stroke="#7c3aed" stroke-width="3"/><text x="70" y="1024" font-size="24" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#6d28d9">④ 安全、雲端與 AI</text><text x="70" y="1068" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#173042">authentication ≠ authorization；hash ≠ encryption；密碼採 salted password hashing＋適當 cost factor。</text><text x="70" y="1106" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#173042">雲端五項 essential characteristics 是判斷基礎；分散式系統還有延遲、部分故障與一致性成本。</text><text x="70" y="1144" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#173042">AI 先分 training、inference、evaluation，再談資料、模型與評估限制。</text><rect x="42" y="1200" width="816" height="46" rx="16" fill="#173042"/><text x="450" y="1230" text-anchor="middle" font-size="15" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#fff">先找它在哪一層；再問資料如何表示、處理、傳輸、儲存與保護</text></svg>\n'''
def apply(site_root,before):
 site=Path(site_root);lp=site/'data/library.json';lib=json.loads(lp.read_text());assert lib['version']==before;root=site/'books'/BOOK;mp=root/'manifest.json';m=json.loads(mp.read_text());assert m['id']==BOOK and m['version']==BOOK_VERSION;changed=False
 fig=f'<figure class="chapter-figure" {VP_MARKER}><a href="{VP_ASSET}" target="_blank" rel="noopener"><img loading="lazy" src="{VP_ASSET}" alt="計算機概論資料硬體作業系統網路程式與安全判斷地圖"></a><figcaption>資料 → 硬體 → OS → 網路 → 程式 → 安全判斷地圖｜點圖可開啟 SVG 大圖放大閱讀。</figcaption></figure>'
 ch=root/'chapters/ch00.html';t=ch.read_text();old='<figure class="chapter-figure"><img loading="lazy" src="assets/computer-fundamentals-svg/computing-map.svg" alt="計算機資訊處理地圖"><figcaption>計算機資訊處理地圖</figcaption></figure>'
 if VP_MARKER not in t:assert old in t;ch.write_text(t.replace(old,fig,1));changed=True
 ap=root/'chapters/appendix-b.html';t=ap.read_text();anchor='<h2 id="進位與容量題">進位與容量題</h2>'
 if VP_MARKER not in t:assert anchor in t;ap.write_text(t.replace(anchor,fig+anchor,1));changed=True
 sp=site/VP_ASSET;sv=svg_text()
 if sp.read_text()!=sv:sp.write_text(sv);changed=True
 vp={'status':'passed','date':'2026-07-31','asset':VP_ASSET,'placement':'ch00 and appendix-b','canvaDesignId':CANVA_DESIGN_ID,'canvaEditUrl':CANVA_EDIT_URL,'tabletReadable':True,'zoomable':True,'offlineCachedViaExistingAssetPath':True}
 if m.get('visualPolish')!=vp:m['visualPolish']=vp;mp.write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n');changed=True
 if changed:
  after=nxt(before);lib['version']=after;lp.write_text(json.dumps(lib,ensure_ascii=False,indent=2)+'\n');swp=site/'sw.js';sw=swp.read_text();sw,n=re.subn(r"const VERSION = 'study-library-[^']+';",f"const VERSION = 'study-library-{after}';",sw,count=1);assert n==1;swp.write_text(sw);return after
 return before
if __name__=='__main__':print(apply(sys.argv[1],sys.argv[2]))
